### 类型

#### 基础图片预览

**WXML** (`html`):
```html
<t-button theme="primary" size="large" variant="outline" block bind:tap="onClick">基础图片预览</t-button>
<t-toast id="t-toast" />
<t-image-viewer
usingCustomNavbar
deleteBtn="{{deleteBtn}}"
closeBtn="{{closeBtn}}"
showIndex="{{showIndex}}"
visible="{{visible}}"
images="{{images}}"
bind:change="onChange"
bind:delete="onDelete"
bind:close="onClose"
></t-image-viewer>

```

**JS** (`javascript`):
```javascript
import Toast from 'tdesign-miniprogram/toast/index';

Component({
data: {
visible: false,
showIndex: false,
closeBtn: false,
deleteBtn: false,
images: [],
},
methods: {
onClick() {
this.setData({
images: [
'https://tdesign.gtimg.com/mobile/demos/swiper1.png',
'https://tdesign.gtimg.com/mobile/demos/swiper2.png',
],
showIndex: true,
visible: true,
});
},
onChange(e) {
const { index } = e.detail;

console.log('change', index);
},

onDelete(e) {
const { index } = e.detail;

Toast({
context: this,
selector: '#t-toast',
message: `删除第${index + 1}个`,
});
},

onClose(e) {
const { trigger } = e.detail;
console.log(trigger);
this.setData({
visible: false,
});
},
},
});

